1	// The task declaration contract (per-project-scheduling DESIGN §1) — the single
2	// source of truth for what a `tasks/<name>/task.mjs` default export must carry.
3	// Both the author-time `task-declaration-shape` check and the executor-side
4	// `validate-dispatch` validate against this one function, so the accepted shape
5	// can never drift between the two surfaces.
6	
7	import { FREQUENCIES } from './slots.mjs';
8	import { MODEL_FAMILIES } from './model-map.mjs';
9	import { EXECUTING_LEASH_MS } from './queue/leases.mjs';
10	
11	// A declared timeout is always a whole number of seconds, > 0.
12	const isPositiveInt = (n) => Number.isInteger(n) && n > 0;
13	
14	// A prework command must stay inside its own task directory — no absolute
15	// path and no `..` traversal in the command string — the same containment the
16	// worker-file rule gives agent_instructions (task-prework DESIGN §2).
17	const escapesTaskDir = (cmd) => /(^|\s)\//.test(cmd) || cmd.includes('..');
18	
19	// The 2026-08-06 phase-language rename (owner): task execution is two similar,
20	// consecutive phases — deterministic PREWORK, then AGENTIC WORK — and the field
21	// names say so instead of framing the code phase as preparation for the agent.
22	// Legacy names stay accepted here (consumer local packs rename on their own
23	// clock, driven by a migration note), canonical names win when both are present.
24	const LEGACY_FIELDS = { agent_preprocessing: 'prework', agent_preprocessing_timeout: 'prework_timeout' };
25	
26	// Return the declaration with canonical field names. Non-objects pass through
27	// untouched so validateTaskDeclaration still reports them. Loaders (discover,
28	// resolve-dispatch) normalize once; everything downstream sees only `prework`.
29	export function normalizeTaskDeclaration(decl) {
30	  if (decl === null || typeof decl !== 'object' || Array.isArray(decl)) return decl;
31	  const out = { ...decl };
32	  for (const [legacy, canonical] of Object.entries(LEGACY_FIELDS)) {
33	    if (out[legacy] !== undefined) {
34	      if (out[canonical] === undefined) out[canonical] = out[legacy];
35	      delete out[legacy];
36	    }
37	  }
38	  return out;
39	}
40	
41	// The write ceiling a task declares (DESIGN §1, §4). A declared MAXIMUM, not a
42	// promise: `none` may never open a PR, `open-pr` may open but never merge,
43	// `merged-pr` may arm auto-merge. "No change" is always legal.
44	export const OUTCOMES = ['none', 'open-pr', 'merged-pr'];
45	
46	
47	// The executor-session dispatch vocabulary — DEPRECATED as a declared field, kept
48	// as routing. 'self' dispatches ride `ready-for-agent`; 'fleet' rides
49	// `ready-for-agent-fleet`, the label whose executor session holds the owner's repos.
50	// A task no longer declares this: a repo's executor carries the access it was
51	// provisioned with (the sheepdog enforcer's already spans the fleet), so the split
52	// protects nothing there. The one standing use is the canon home's curation tasks
53	// (growth-promote, growth-discover-packs), whose fleet executor is a separate,
54	// broader-scoped routine in that one repo.
55	export const SESSION_SCOPES = ['self', 'fleet'];
56	
57	// What must happen to a task's work item when a recovery path would re-execute it
58	// (tasks-dispatch DESIGN §6). `requeue` is the safe-side default for sweep-shaped
59	// work; `needs-human` is the at-most-once dial a one-shot side effect declares.
60	export const INTERRUPT_POLICIES = ['requeue', 'needs-human'];
61	
62	
63	// The signal-collector vocabulary (DESIGN §3.3). A task collects only the union
64	// of what its due tasks declare. `fleet` is canon-only (consumers cannot declare
65	// it) — that restriction is enforced where signals are collected, not here; the
66	// shape check only asserts a declared name is a real collector.
67	export const SIGNAL_NAMES = [
68	  'commits', 'prs', 'issues', 'branches', 'release',
69	  'localPacks', 'sharedMount', 'conversationLogs', 'stamp', 'fleet',
70	];
71	
72	// Validate one task declaration. Returns an array of `{ what, fix }` problems —
73	// empty means the declaration is well-formed. Pure: no I/O, no imports of the
74	// task itself; the caller supplies the already-loaded default export.
75	export function validateTaskDeclaration(raw) {
76	  const decl = normalizeTaskDeclaration(raw);
77	  if (decl === null || typeof decl !== 'object' || Array.isArray(decl)) {
78	    return [{ what: 'task.mjs does not default-export a declaration object', fix: 'export default { id, frequency, precondition_signals, agent_model, expected_outcome, agent_instructions, precondition }' }];
79	  }
80	  const problems = [];
81	  const bad = (what, fix) => problems.push({ what, fix });
82	
83	  if (typeof decl.id !== 'string' || decl.id.trim() === '') {
84	    bad('the task has no string "id"', 'give the task an "id" matching its directory name');
85	  }
86	  if (!FREQUENCIES.includes(decl.frequency)) {
87	    bad(`"frequency" ${JSON.stringify(decl.frequency)} is not a legal frequency`, `set one of: ${FREQUENCIES.join(', ')}`);
88	  }
89	  if (!Array.isArray(decl.precondition_signals) || !decl.precondition_signals.every((s) => SIGNAL_NAMES.includes(s))) {
90	    bad(`"precondition_signals" must be an array of known signal names`, `use only: ${SIGNAL_NAMES.join(', ')}`);
91	  }
92	  if (!MODEL_FAMILIES.includes(decl.agent_model)) {
93	    bad(`"agent_model" ${JSON.stringify(decl.agent_model)} is not a legal model family`, `set one of: ${MODEL_FAMILIES.join(', ')}`);
94	  }
95	  if (!OUTCOMES.includes(decl.expected_outcome)) {
96	    bad(`"expected_outcome" ${JSON.stringify(decl.expected_outcome)} is not a legal outcome ceiling`, `set one of: ${OUTCOMES.join(', ')}`);
97	  }
98	  // agent_instructions — REQUIRED for an agentic task (agent_model !== 'none'):
99	  // that's the worker file the agent reads. A `none` task runs no agent, so the
100	  // field is not applicable and is neither required nor validated when present.
101	  if (decl.agent_model !== 'none' && (typeof decl.agent_instructions !== 'string' || decl.agent_instructions.trim() === '')) {
102	    bad('an agentic task (agent_model !== "none") declares no string "agent_instructions"', 'point "agent_instructions" at the worker file beside task.mjs (e.g. "task.md")');
103	  }
104	  if (typeof decl.precondition !== 'function') {
105	    bad('"precondition" is not a function', 'export a precondition(signals, config) that returns { run, reason, context? }');
106	  }
107	
108	  /**
109	   * session_scope — OPTIONAL; still honoured while it lingers (the canon's
110	   * curation tasks are the one standing use — each pacifies the warning with a
111	   * comment at its declaration site). It stays VALIDATED rather than ignored: a
112	   * deprecated field that silently accepts a typo mis-routes the dispatch to an
113	   * executor that declines it, and the task then never runs while the scheduler
114	   * re-arms it hourly.
115	   * @deprecated An executor's reach is how its repo is provisioned, never
116	   *   something a task asks for — drop the field; dispatches ride ready-for-agent.
117	   */
118	  if (decl.session_scope !== undefined && !SESSION_SCOPES.includes(decl.session_scope)) {
119	    bad(`"session_scope" ${JSON.stringify(decl.session_scope)} is not a legal session scope`, `drop it (dispatches ride ready-for-agent by default) — or, while it lingers, set one of: ${SESSION_SCOPES.join(', ')}`);
120	  }
121	
122	  // Prework (task-prework DESIGN §2) — OPTIONAL. The deterministic first phase
123	  // of task execution, a command the scheduler runs as a subprocess. When present
124	  // it must be a non-empty, task-local command AND carry a positive-integer
125	  // prework_timeout — the hard kill that bounds the subprocess.
126	  if (decl.prework !== undefined) {
127	    if (typeof decl.prework !== 'string' || decl.prework.trim() === '') {
128	      bad('"prework" is present but not a non-empty string', 'set it to a command whose executable is a script beside task.mjs, e.g. "node prepare.mjs"');
129	    } else if (escapesTaskDir(decl.prework)) {
130	      bad('"prework" reaches outside the task directory (absolute path or "..")', 'reference a sibling script only, e.g. "node prepare.mjs"');
131	    }
132	    if (!isPositiveInt(decl.prework_timeout)) {
133	      bad('"prework" is set but "prework_timeout" is not a positive integer', 'add "prework_timeout": the seconds after which the subprocess is killed and the task fails');
134	    } else if (decl.prework_timeout * 1000 >= EXECUTING_LEASH_MS) {
135	      // F17: a prework legally allowed to outlive the executing leash is reclaimed
136	      // WHILE ALIVE, and the failure is not one duplicate run but a livelock —
137	      // every tenure reclaimed before it can finish, prework re-executing each
138	      // cycle, the occurrence never converging. The leash is the engine's, so the
139	      // comparison is made where a declaration is judged.
140	      bad(`"prework_timeout" (${decl.prework_timeout}s) reaches the executor's ${EXECUTING_LEASH_MS / 60e3}-minute claim leash`,
141	        `bound prework under ${EXECUTING_LEASH_MS / 60e3} minutes — a prework that can outlive the leash is reclaimed while still running, and the item livelocks`);
142	    }
143	  }
144	
145	  // --- the work-item queue's three optional declarations (tasks-dispatch DESIGN) ---
146	
147	  // `after` — ordering, declared (DESIGN §9). A list of `<pack>/<task>` ids this
148	  // task yields to WHILE THEY ARE LIVE THIS CYCLE. It compiles to the executor's
149	  // pick-time yield, never to a `Blocked-by` edge: a standing item that rolls
150	  // never closes, so blocked-by would starve every dependent of a quiet upstream
151	  // forever. The engine never learns what any named task does — it reads item
152	  // states, generically.
153	  if (decl.after !== undefined
154	      && !(Array.isArray(decl.after) && decl.after.every((s) => typeof s === 'string' && /^[^/\s]+\/[^/\s]+$/.test(s)))) {
155	    bad('"after" is not an array of "<pack>/<task>" ids', 'e.g. "after": ["core/update"] — this task yields while those are live this cycle');
156	  }
157	
158	  // `on_interrupt` — the ack-early/ack-late dial (DESIGN §6). Most of this fleet's
159	  // tasks are sweep-shaped and converge safely on a re-run, so the default is
160	  // `requeue`. A genuinely one-shot side effect (a store submission, an external
161	  // notification) declares `needs-human`, and every recovery path that would
162	  // re-execute it — the leash reclaim, the hand-off retry — converges to triage
163	  // instead: at-most-once plus a human.
164	  if (decl.on_interrupt !== undefined && !INTERRUPT_POLICIES.includes(decl.on_interrupt)) {
165	    bad(`"on_interrupt" ${JSON.stringify(decl.on_interrupt)} is not a legal policy`, `set one of: ${INTERRUPT_POLICIES.join(', ')} (default "requeue")`);
166	  }
167	
168	  // `invocation_endpoint` — a NAME, never a URL (DESIGN §12). The repo's config
169	  // maps the name to the URL and to the name of the Actions secret holding its
170	  // token, so no vendored pack file carries deployment detail or anything adjacent
171	  // to a credential. This is also what replaces session_scope: reach is a property
172	  // of which endpoint a task names.
173	  if (decl.invocation_endpoint !== undefined
174	      && !(typeof decl.invocation_endpoint === 'string' && /^[a-z0-9]+(-[a-z0-9]+)*$/.test(decl.invocation_endpoint))) {
175	    bad('"invocation_endpoint" is not a kebab-case endpoint name', 'name a key from the repo\'s taskScheduler.endpoints map, e.g. "fleet" — never a URL');
176	  }
177	
178	  // The repo Actions secrets this task needs configured (DESIGN §9). Purely
179	  // DECLARATIVE — like a pack's adoption `questions`, its job is to drive the ask
180	  // (adoption interactively, the scheduler by owner issue), not to gate anything
181	  // here. So the only shape asserted is "a list of names"; whether the repo has
182	  // actually configured them is a fact about the repo, answered where the secrets
183	  // bundle is readable, never at author time.
184	  if (decl.required_secrets !== undefined
185	      && !(Array.isArray(decl.required_secrets) && decl.required_secrets.every((s) => typeof s === 'string' && s.trim() !== ''))) {
186	    bad('"required_secrets" is not an array of secret names', 'list the repo Actions secret names this task needs, e.g. ["SOME_API_KEY"]');
187	  }
188	
189	  // Execution bound (task-prework DESIGN §2, §6) — an agentic task MUST
190	  // declare a positive-integer agent_execution_timeout. There is always a bound
191	  // on an agentic run; enforcement is best-effort (the executor surfaces the
192	  // value to the subagent). A `none` task runs no agent, so it needs none.
193	  if (MODEL_FAMILIES.includes(decl.agent_model) && decl.agent_model !== 'none' && !isPositiveInt(decl.agent_execution_timeout)) {
194	    bad('an agentic task (agent_model !== "none") declares no positive-integer "agent_execution_timeout"', 'add "agent_execution_timeout": the seconds bounding the agentic run — generous; extreme protection, not a scheduling knob');
195	  }
196	
197	  // An agentless task (agent_model: none) runs no agent, so its ONLY work is
198	  // prework — a `none` task with no prework does nothing (DESIGN §4, retiring
199	  // the in-process inline path). Require the command.
200	  if (decl.agent_model === 'none' && decl.prework === undefined) {
201	    bad('an agentless task (agent_model: "none") declares no "prework"', 'add "prework" (a none task does its work in that subprocess) — or give the task an agent_model');
202	  }
203	
204	  return problems;
205	}
