  const out = { ...decl };
  for (const [legacy, canonical] of Object.entries(LEGACY_FIELDS)) {
    if (out[legacy] !== undefined) {
      if (out[canonical] === undefined) out[canonical] = out[legacy];
      delete out[legacy];
    }
