    } else if (escapesTaskDir(decl.prework)) {
      bad('"prework" reaches outside the task directory (absolute path or "..")', 'reference a sibling script only, e.g. "node prepare.mjs"');
    }
    if (!isPositiveInt(decl.prework_timeout)) {
