    bad('"required_secrets" is not an array of secret names', 'list the repo Actions secret names this task needs, e.g. ["SOME_API_KEY"]');
  }

  // Execution bound (task-prework DESIGN §2, §6) — an agentic task MUST
  // declare a positive-integer agent_execution_timeout. There is always a bound
  // on an agentic run; enforcement is best-effort (the executor surfaces the
  // value to the subagent). A `none` task runs no agent, so it needs none.
  if (MODEL_FAMILIES.includes(decl.agent_model) && decl.agent_model !== 'none' && !isPositiveInt(decl.agent_execution_timeout)) {
    bad('an agentic task (agent_model !== "none") declares no positive-integer "agent_execution_timeout"', 'add "agent_execution_timeout": the seconds bounding the agentic run — generous; extreme protection, not a scheduling knob');
  }

  // An agentless task (agent_model: none) runs no agent, so its ONLY work is
  // prework — a `none` task with no prework does nothing (DESIGN §4, retiring
  // the in-process inline path). Require the command.
  if (decl.agent_model === 'none' && decl.prework === undefined) {
    bad('an agentless task (agent_model: "none") declares no "prework"', 'add "prework" (a none task does its work in that subprocess) — or give the task an agent_model');
  }

  return problems;
}

// The executor (tasks-dispatch DESIGN §6) — a pull worker over the queue. Each
// iteration: pick the next ready item, claim it by a verified lease, evaluate the
// precondition (THE only place it is ever evaluated), then on a go run prework and
// either converge (agentless) or hand off to an agent session; on a no-go roll a
// scheduled item to its next anchor with the reason on record.
//
// An executor's whole interface is issue read/write plus the repo at HEAD, which
// is what makes it platform-agnostic: the reference deployment is a job in the
// vendored workflows (the tick's post-tick drain, and a `labeled`-event run for
// latency), but a runner anywhere with an issues-scope token qualifies. Nothing
// enumerates executors; identity is self-declared in the claim comment.
//
// The pure decisions live at the top and test with fixtures; the shell below is
// the GitHub/prework/invocation I/O around them.

import { pathToFileURL } from 'node:url';
import { nextAnchor } from './anchors.mjs';
import {
  READY, URGENT, EXECUTING, AGENT, BLOCKED, NEEDS_HUMAN, ORIGIN_SCHEDULE,
  OUTCOME_DONE, OUTCOME_DELIVERED, OUTCOME_OBSOLETE, QUEUE_LABELS,
  CLAIM_MARKER, HANDOFF_MARKER, EPISODE_MARKER,
  parseWorkItemTitle, parseWorkItemBody, withNotBefore, withSection, hasLabel,
} from './work-item.mjs';

// How many items one executor run may take before it stops. Small on purpose: an
// executor is code iterating a queue, and more capacity is more executors, not a
// longer loop (DESIGN §10).
export const DEFAULT_MAX_ITEMS = 3;

const titleOf = (item) => (item.title ?? '').trim();
const taskIdOf = (item) => {
  const p = parseWorkItemTitle(item.title);
  return p ? `${p.pack}/${p.task}` : null;
};

// The pick order (DESIGN §6.1): urgent first, then oldest-created, with two skip
// rules read live at pick time.
//
//  - SAME-TITLE MUTEX (S15/F6): skip an item whose exact title has another open
//    item executing or handed to an agent — one task, one execution at a time,
//    while a fan-out's distinct qualifiers still parallelize.
//  - THE `after` YIELD (S24): skip a scheduled item whose task declares `after:
//    [T]` while T's standing item is live THIS CYCLE (ready / executing / agent).
//    A rolled upstream (blocked until its next anchor: it declined this cycle)
//    does not block, and neither does one sitting `needs-human` — a broken
//    upstream must not halt its dependents indefinitely. Deliberately NOT a
//    `Blocked-by` edge: a standing item that rolls never closes, so blocked-by
//    would starve every dependent of a quiet upstream forever.
//
// `open` is every open work item; `taskAfter(id)` gives a task's declared
// upstreams as `<pack>/<task>` ids.
export function pickOrder(open = [], { taskAfter = () => [] } = {}) {
  const live = (item) => hasLabel(item, READY) || hasLabel(item, EXECUTING) || hasLabel(item, AGENT);
  const liveUpstream = (upstreamId) => open.some((o) =>
    taskIdOf(o) === upstreamId && hasLabel(o, ORIGIN_SCHEDULE) && live(o));

  return open
    .filter((i) => hasLabel(i, READY) && !hasLabel(i, NEEDS_HUMAN))
    .filter((i) => !open.some((o) => o.number !== i.number && titleOf(o) === titleOf(i)
      && (hasLabel(o, EXECUTING) || hasLabel(o, AGENT))))
    .filter((i) => {
      if (!hasLabel(i, ORIGIN_SCHEDULE)) return true;
      return !taskAfter(taskIdOf(i)).some(liveUpstream);
    })
    .sort((a, b) =>
      (hasLabel(b, URGENT) ? 1 : 0) - (hasLabel(a, URGENT) ? 1 : 0)
      || new Date(a.created_at) - new Date(b.created_at)
      || a.number - b.number);
}

// The claim comment carries WHO and WHEN — the executor id and its run URL —
// because executor identity is an unbounded set and must never become a label
// (DESIGN §4).
export const claimComment = ({ executor, runUrl, at }) =>
  `${CLAIM_MARKER}\nClaimed by executor \`${executor}\` at ${at}.${runUrl ? `\n\nRun: ${runUrl}` : ''}`;

// Who won the claim, out of an item's comments (DESIGN §6.2). Three precisions,
// each an implicit assumption made explicit:
//
//  - "EARLIEST" MEANS LOWEST COMMENT ID, never timestamp. GitHub comment
//    `created_at` has one-second granularity, so simultaneous claims tie on time;
//    comment ids are server-assigned and strictly increasing — a total order the
//    protocol gets for free. Nothing here compares runner clocks.
//  - THE ARBITER IS EPISODE-SCOPED (F18): the earliest claim SINCE the item last
//    became ready. Over an item's lifetime dead claims accumulate (every reclaim
//    and revert leaves one), and arbitrating over all of them makes a dead claim
//    outrank every future live claimant — the item then livelocks through reclaim
//    cycles forever. The reclaim / revert / re-queue comment is the boundary.
//  - THE LABEL SWAP IS NOT THE ARBITER, so a torn swap can never mint a second
//    owner; it can only leave an item with no state label, which the janitor
//    repairs.
export function claimWinner(comments = []) {
  const sorted = [...comments].sort((a, b) => a.id - b.id);
  const boundary = sorted.filter((c) => (c.body ?? '').includes(EPISODE_MARKER)).at(-1);
  const claims = sorted
    .filter((c) => (c.body ?? '').includes(CLAIM_MARKER))
    .filter((c) => !boundary || c.id > boundary.id);
  return claims[0] ?? null;
}

// After WINNING a claim, re-verify the pick filters against live state (F15). The
// filters read possibly-stale state, so two executors can pass them simultaneously
// and claim DIFFERENT items the filters should have serialized — a twin pair, or
// an upstream and its dependent. The per-item lease cannot see that: it protects
// one item, not one title. If a conflicting item now holds an EARLIER claim
// (comment id — the same arbiter the lease trusts), this executor reverts its own
// claim and moves on. Bounded, deterministic, and the earlier claim never notices.
export function conflictsWithEarlierClaim(item, myClaimId, others, { taskAfter = () => [] } = {}) {
  const upstreams = hasLabel(item, ORIGIN_SCHEDULE) ? taskAfter(taskIdOf(item)) : [];
  return others.some((o) => {
    if (o.number === item.number) return false;
    if (!(hasLabel(o, EXECUTING) || hasLabel(o, AGENT))) return false;
    const conflicting = titleOf(o) === titleOf(item)
      || (upstreams.includes(taskIdOf(o)) && hasLabel(o, ORIGIN_SCHEDULE));
    return conflicting && o.claimId != null && o.claimId < myClaimId;
  });
}

// The no-go outcome (DESIGN §6.4). A SCHEDULED item rolls — `Not-before` stamped
// with the task's next anchor, ready → blocked, the reason recorded — so the item

// The work item — the queue's one durable object (tasks-dispatch DESIGN §3, §4).
// An issue titled `[claudinite-work] <pack>/<task> [qualifier]`, whose labels are
// its state, whose body's first line is the task path, and whose two optional body
// fields (`Not-before`, `Blocked-by`) are the only scheduling facts it carries.
//
// PURE, and deliberately the whole schema: everything else — anchors, guards,
// yields, leashes, verdicts — is computed fresh at every tick and pick from the
// engine and the declarations at HEAD (DESIGN §14). The label-and-field vocabulary
// here is therefore the compatibility surface across engine versions, which is why
// additive change is the strongly preferred shape and a rename needs a migration.
//
// Parse/serialize of the two fields lives here and nowhere else (DESIGN §9).

// The title prefix. Disjoint from the slot mechanism's `[claudinite-task]` on
// purpose: the two mechanisms coexist per-repo behind `taskScheduler.dispatch`,
// and neither may read the other's issues (DESIGN §14, S29).
export const WORK_PREFIX = '[claudinite-work]';

export const BLOCKED = 'task:blocked';
export const READY = 'task:ready';
export const URGENT = 'task:urgent';
export const EXECUTING = 'task:executing';
export const AGENT = 'task:agent';
export const ORIGIN_SCHEDULE = 'origin:schedule';
export const NEEDS_HUMAN = 'needs-human';
export const OUTCOME_DONE = 'outcome:done';
export const OUTCOME_DELIVERED = 'outcome:delivered';
export const OUTCOME_OBSOLETE = 'outcome:obsolete';

// The four state labels an open item may wear. An open item wearing none of them
// and no `needs-human` is off the state machine entirely — a torn label swap's
// leavings, which the janitor repairs (DESIGN §6.2, §11).
export const STATE_LABELS = [BLOCKED, READY, EXECUTING, AGENT];

// Every label this mechanism applies, with the colour and description a bootstrap
// one-off would have given it. Ensured create-if-missing before anything is
// applied: GitHub 422s when you apply an unknown label and never creates one on
// demand, so the thing that assigns a label guarantees it first.
export const QUEUE_LABELS = [
  { name: BLOCKED, color: 'c5def5', description: 'Claudinite queue: waiting on Blocked-by and/or Not-before' },
  { name: READY, color: '0e8a16', description: 'Claudinite queue: available for an executor to pick up' },
  { name: URGENT, color: 'd93f0b', description: 'Claudinite queue: pick this before any non-urgent item' },
  { name: EXECUTING, color: 'fbca04', description: 'Claudinite queue: an executor holds the claim' },
  { name: AGENT, color: '1d76db', description: 'Claudinite queue: an agent session owns this item' },
  { name: ORIGIN_SCHEDULE, color: 'ededed', description: 'Claudinite queue: created by the generator tick at a task anchor' },
  { name: NEEDS_HUMAN, color: 'b60205', description: 'Claudinite queue: failed or anomalous — the one triage state' },
  { name: OUTCOME_DONE, color: '0e8a16', description: 'Claudinite queue: succeeded, nothing pending' },
  { name: OUTCOME_DELIVERED, color: '5319e7', description: 'Claudinite queue: succeeded and left a live artifact the world still has to act on' },
  { name: OUTCOME_OBSOLETE, color: 'ededed', description: 'Claudinite queue: never ran — the precondition said no, or the task is gone' },
];

// GitHub hands labels back as objects on the issues API and as bare strings in
// some fixtures; accept either.
export const labelNames = (issue) =>
  (issue?.labels ?? []).map((l) => (typeof l === 'string' ? l : l?.name)).filter(Boolean);

export const hasLabel = (issue, name) => labelNames(issue).includes(name);

// Title. The optional qualifier exists ONLY for deliberately concurrent items —
// a fan-out naming its target — and it is part of the identity the same-title
// mutex reads (DESIGN §6.1). Nothing ever encodes a date here: that was the slot
// grammar, and the issue number is the identity (DESIGN §5).
export const workItemTitle = ({ pack, task, qualifier = null }) =>
  `${WORK_PREFIX} ${pack}/${task}${qualifier ? ` ${qualifier}` : ''}`;

// pack and task ids are single path segments; the qualifier is whatever follows.
const TITLE_RE = /^\[claudinite-work\]\s+([^/\s]+)\/([^/\s]+)(?:\s+(\S.*))?$/;

export function parseWorkItemTitle(title) {
  const m = TITLE_RE.exec(String(title ?? '').trim());
  return m ? { pack: m[1], task: m[2], qualifier: m[3]?.trim() || null } : null;
}

export const isWorkItemTitle = (title) => parseWorkItemTitle(title) !== null;

// --- comment markers ----------------------------------------------------------
// The three comments the protocol reads back. They are HTML comments so a human
// reading the item sees prose, and they are here — with the labels and the body
// fields — because together they ARE the item's vocabulary, the one compatibility
// surface across engine versions (DESIGN §14).

// grow_with_claudinite task: growth-discover-packs — LOCAL pack discovery, per repo
// (per-project-scheduling redesign). Each repo periodically reflects on its OWN
// stack and captured knowledge: knowing the canon packs already available to it, if
// it notices project-specific knowledge worth organizing into a new LOCAL pack — a
// segment of the repo's own tree whose work no canon pack homes and its existing local
// packs don't yet capture; never a technology or methodology pack, which is the
// canon-side promote stage's call — it authors that local pack. A per-repo, local operation: it
// writes only the repo's OWN `.claudinite/local/packs/` (the shared canon stays
// human-gated — lifting a local pack up is the central promote task's job).
//
// Reviewed, NOT auto-merged, unlike growth-extract. Extract adds prose or a rule to
// territory a local pack already owns; a NEW pack ships new `.mjs` conformance checks
// that run at every Stop and in CI from the moment it merges, so a wrong or over-eager
// one breaks the repo with nobody having looked. Same reason the sibling
// prose-to-checks-sweep declares open-pr — a check can break CI, so it's reviewed.
// expected_outcome is a hard ceiling the executor enforces (verify-outcome.mjs), so
// this declaration is what actually keeps auto-merge off the PR.
//
// Self-contained (imports nothing): the whole contract is this default export.

export default {
  id: 'growth-discover-packs',
  frequency: 'weekly',                   // a repo's stack is slow-moving — a weekly reflection, not a daily one
  precondition_signals: [],              // it examines the repo's own checkout in-session, not a windowed signal
  agent_model: 'opus',                   // judging what is genuinely pack-worthy and authoring a pack is heavy judgment
  expected_outcome: 'open-pr',           // a new pack can ship new .mjs checks, and a check can break CI, so it's reviewed
  agent_instructions: 'task.md',
  agent_execution_timeout: 2400,         // manifest the stack + author a local pack — a generous weekly bound

  // Fires weekly. There is no windowed trigger — the opportunity is standing
  // (project-specific knowledge that was never organized into a pack, not a recent
  // change), so the worker examines the repo each week and no-ops cheaply when
  // there is nothing new worth a local pack.
  precondition() {
    return { run: true, reason: 'weekly local pack-discovery reflection (no-ops when nothing new is pack-worthy)' };
  },
};

